    (usp0 + -128 <= a \/ (0x10000 <= a < 0x5d000 /\ ~ (RERRNO <= a < RERRNO + 4) /\ ~ (UREAD_STAGE <= a < UREAD_STAGE + 65536))) -> outside W a.
